// edge: the middleware re-evaluates the policy on every request - no trusting the session
app.MapGet("/records/{id}", async (string id, IVault vault,
        IAuthorizationService auth, ClaimsPrincipal user) =>
{
    var record = await vault.GetAsync(id);                       // load the resource first
    var result = await auth.AuthorizeAsync(user, record, "CanReadRecord");  // decide at the point of use
    return result.Succeeded ? Results.Ok(record) : Results.Forbid();
});
